+  padding: 1.1rem 1.4rem;
+  background: #1a1f2e;
+  border: none;
+  color: #e2e8f0;
+  font-size: 1rem;
+  font-weight: 600;
+  text-align: left;
+  cursor: pointer;
+  transition: background 0.2s ease, color 0.2s ease;
+}
+
+.question:hover {
+  background: #212840;
+  color: #a5b4fc;
+}
+
+.question:focus-visible {
+  outline: 2px solid #6366f1;
+  outline-offset: -2px;
+}
+
+.question[aria-expanded="true"] {
+  background: #1e2340;
+  color: #a5b4fc;
+}
+
+/* ── +/× icon ──────────────────────────────────────────────────── */
+.icon {
+  flex-shrink: 0;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 1.5rem;
+  height: 1.5rem;
+  border-radius: 50%;
+  background: #2d3748;
+  font-size: 1.1rem;
+  font-weight: 400;
+  line-height: 1;
+  color: #94a3b8;
