+
+/* inner wrapper needed for grid row animation trick */
+.details > p {
+  overflow: hidden;
+  color: #94a3b8;
+  font-size: 0.95rem;
+}
+
+.details > p em {
+  color: #c7d2fe;
+  font-style: italic;
+}
